193	     * Try to find a free location that is adjacent to the
194	     * given location. If there is none, return null.
195	     * The returned location will be within the valid bounds
196	     * of the field.
197	     * @param actor The actor finding a free adjacent location.
198	     * @param location The location from which to generate an adjacency.
199	     * @return A valid location within the grid area.
200	     */
201	    public Location freeAdjacentLocation(Actor actor, Location location)
202	    {
203	        // The available free ones.
204	        List<Location> free = getFreeAdjacentLocations(actor, location);
