213	    /**
214	     * Return a shuffled list of locations adjacent to the given one.
215	     * The list will not include the location itself.
216	     * All locations will lie within the grid.
217	     * @param location The location from which to generate adjacencies.
218	     * @return A list of locations adjacent to that given.
219	     */
220	    public List<Location> adjacentLocations(Location location)
221	    {
222	        assert location != null : "Null location passed to adjacentLocations";
223	        // The list of locations to be returned.
224	        List<Location> locations = new LinkedList<>();
225	        if(location != null) {
226	            int row = location.getRow();
227	            int col = location.getCol();
228	            for(int roffset = -1; roffset <= 1; roffset++) {
229	                int nextRow = row + roffset;
230	                if(nextRow >= 0 && nextRow < depth) {
231	                    for(int coffset = -1; coffset <= 1; coffset++) {
232	                        int nextCol = col + coffset;
233	                        // Exclude invalid locations and the original location.
234	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
235	                            locations.add(new Location(nextRow, nextCol));
236	                        }
237	                    }
238	                }
239	            }
240	
241	            // Shuffle the list. Several other methods rely on the list
242	            // being in a random order.
243	            Collections.shuffle(locations, rand);
244	        }
245	        return locations;
246	    }
