152	                                setDiseases.add(disease);
153	                            }
154	                        }
155	                        prey.setDead();
156	                        foodLevel = Math.min(foodLevel + foodValue, getMaxFood());
157	                        return where;
158	                    }
159	                }
160	            }
161	        }
162	        return null;
163	    }
