206	    {
207	        Random rand = Randomizer.getRandom();
208	        field.clear();
209	        for(int row = 0; row < field.getDepth(); row++) {
210	            for(int col = 0; col < field.getWidth(); col++) {
211	                for (Actor actor : actorCreationProb.keySet()){
212	                    Location location = new Location(row, col);
213	                    if(rand.nextDouble() <= actorCreationProb.get(actor) && field.canOccupy(actor, location)) {
214	                        Actor newActor = actor.birth(new Location(row, col));
215	                        actors.add(newActor);
216	                        break;
217	                    }
218	                }
219	            }
220	        }
221	    }
